// Voice clips: the Tambola announcer (/public/audio/tambola) and Filmy Dialogues
// (/public/audio/filmy), pre-generated by scripts/gen-audio.mjs, which writes each folder's
// manifest.json. Clips play one at a time, ducking the background music while speaking.
// Falls back to the browser's speech engine. Keys: 'n25' / 'bogey' (Tambola), 'filmy/d-sholay'.
import { clipName, clipText, LINES } from '../games/tambola/calls';
import { filmyClipText } from '../games/filmy/data';
import { duckMusic } from './music';

interface Manifest {
  ext: string;
  voice?: string;
  durations: Record<string, number>; // seconds, by file name
  pools?: Record<string, number>; // variants recorded per event line
}

const PACKS = ['tambola', 'filmy'];
const manifests: Record<string, Manifest> = {};
let muted = false;
let queue: string[] = [];
let playing = false;
let token = 0;
let current: HTMLAudioElement | null = null;

export function setMuted(m: boolean) {
  muted = m;
  if (m) {
    queue = [];
    if (current) current.pause();
    try {
      window.speechSynthesis && window.speechSynthesis.cancel();
    } catch {
      /* ignore */
    }
    finish();
  }
}
export function isMuted() {
  return muted;
}

export function loadVoices() {
  for (const pack of PACKS) {
    if (manifests[pack]) continue;
    fetch('/audio/' + pack + '/manifest.json', { cache: 'no-cache' })
      .then((r) => (r.ok && (r.headers.get('content-type') || '').indexOf('json') >= 0 ? r.json() : null))
      .then((m) => {
        if (m && m.durations) manifests[pack] = m;
      })
      .catch(() => {});
  }
}

/** 'filmy/d-sholay' -> ['filmy', 'd-sholay']; anything else is a Tambola key. */
function split(key: string): [string, string] {
  const i = key.indexOf('/');
  return i > 0 ? [key.slice(0, i), key.slice(i + 1)] : ['tambola', key];
}

function textOf(path: string): string {
  const [pack, file] = split(path);
  return pack === 'filmy' ? filmyClipText(file) : clipText(file);
}

const lastPick: Record<string, number> = {};

function variants(key: string): number {
  const manifest = manifests.tambola;
  const recorded = manifest && manifest.pools && manifest.pools[key];
  return recorded || (LINES[key] ? LINES[key].length : 0);
}

/** Clip for a voice key: 'n25' -> '25'; 'bogey' -> 'bogey-2' (random, never the same one twice running); 'filmy/x' as is. */
function fileFor(key: string): string {
  if (key.indexOf('/') > 0) return key;
  if (/^n\d+$/.test(key)) return key.slice(1);
  const count = variants(key);
  if (!count) return key;
  let i = 1 + Math.floor(Math.random() * count);
  if (count > 1 && i === lastPick[key]) i = (i % count) + 1;
  lastPick[key] = i;
  return clipName(key, i);
}

function fileMs(path: string): number {
  const [pack, file] = split(path);
  const m = manifests[pack];
  const d = m && m.durations[file];
  if (d) return Math.round(d * 1000);
  return Math.round(textOf(path).length * 75); // rough speaking rate
}

/** How long a line takes to say (ms), so the game can wait for the announcer. Event lines: the longest variant. */
export function voiceMs(key: string): number {
  if (muted) return 0;
  if (key.indexOf('/') > 0) return fileMs(key);
  if (/^n\d+$/.test(key)) return fileMs(key.slice(1));
  let max = 0;
  for (let i = 1; i <= variants(key); i++) max = Math.max(max, fileMs(clipName(key, i)));
  return max;
}

export function playVoice(key: string) {
  if (muted) return;
  if (key.indexOf('/') > 0) {
    // a film clip cuts off whatever is still playing (e.g. the last question was skipped)
    queue = [];
    token++;
    if (current) current.pause();
    try {
      window.speechSynthesis && window.speechSynthesis.cancel();
    } catch {
      /* ignore */
    }
    playing = false;
  }
  // Never let a backlog build up: drop pending filler lines first.
  if (queue.length >= 2) queue = queue.filter((f) => f.indexOf('hype') !== 0);
  queue.push(fileFor(key));
  if (!playing) next();
}

function finish() {
  playing = false;
  duckMusic('voice', false);
}

function next() {
  const file = queue.shift();
  if (!file) return finish();
  playing = true;
  duckMusic('voice', true);
  const my = ++token;
  const done = () => {
    if (my !== token) return;
    token++;
    if (current) current.pause();
    next();
  };
  // safety net in case 'ended' never fires
  setTimeout(done, fileMs(file) + 2500);
  const [pack, name] = split(file);
  const manifest = manifests[pack];
  const fallback = () => speak(textOf(file), done);
  if (!manifest) return fallback();
  try {
    const a = new Audio('/audio/' + pack + '/' + name + '.' + manifest.ext);
    current = a;
    a.onended = done;
    a.onerror = fallback;
    const p = a.play();
    if (p && p.catch) p.catch(fallback);
  } catch {
    fallback();
  }
}

function speak(text: string, done: () => void) {
  try {
    const synth = window.speechSynthesis;
    if (!synth || !text) return done();
    const u = new SpeechSynthesisUtterance(text);
    const lang = /[\u0900-\u097F]/.test(text) ? 'hi-IN' : 'en-IN'; // the host's lines are in Hindi
    u.lang = lang;
    u.rate = 1;
    const voices = synth.getVoices();
    const v = voices.find((x) => x.lang === lang) || voices.find((x) => x.lang.indexOf(lang.slice(0, 2)) === 0);
    if (v) u.voice = v;
    u.onend = done;
    u.onerror = done;
    synth.speak(u);
  } catch {
    done();
  }
}
